use async_trait :: async_trait ; use derive_setters :: Setters ; use forge_domain :: { ContextMessage , Conversation , EventData , EventHandle , RequestPayload , Role , TextMessage , ToolCallArguments , ToolName , } ; use forge_template :: Element ; use tracing :: warn ; use crate :: TemplateEngine ; use forge_domain :: { Context , ContextMessage , ConversationId , MessageEntry , ToolCallArguments , ToolCallFull , } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Detector for identifying doom loops - when tool calls form repetitive"] # [doc = " patterns"] # [doc = ""] # [doc = " This detector analyzes conversation history to identify two types of loops:"] # [doc = " 1. Consecutive identical calls: [A,A,A,A] - same tool with same arguments"] # [doc = " 2. Repeating patterns: [A,B,C][A,B,C][A,B,C] - sequence of calls repeating"] # [doc = ""] # [doc = " Both patterns indicate the agent is stuck in a loop, wasting tokens without"] # [doc = " making progress."] # [doc = ""] # [doc = " Can be used as a hook on `on_request` events to detect doom loops after"] # [doc = " tool call records from prior turns are already persisted in context."] # [derive (Debug , Clone , Setters)] pub struct DoomLoopDetector { # [doc = " Threshold for consecutive identical tool calls before triggering"] # [doc = " detection"] threshold : usize , }